export function ItemDetail({
  item,
  imageUrl,
  brandSuggestions,
}: {
  item: DetailItem;
  imageUrl: string;
  brandSuggestions: string[];
}) {
  const router = useRouter();
  const [name, setName] = useState(item.name ?? "");
